export const PHOTO_FEMALE_TEACHER = `data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="24 8 112 112"><defs><linearGradient id="bgF" x1="0%" y1="0%" x2="100%" y2="100%"><stop offset="0%" stop-color="%23fdf2f8"/><stop offset="100%" stop-color="%23fce7f3"/></linearGradient><linearGradient id="skinF" x1="0%" y1="0%" x2="0%" y2="100%"><stop offset="0%" stop-color="%23ffdfba"/><stop offset="100%" stop-color="%23f5b88c"/></linearGradient></defs><rect width="160" height="160" fill="url(%23bgF)"/><path d="M62 76 L98 76 L98 94 L62 94 Z" fill="%23f5b88c"/><path d="M4 160 C4 96 40 84 80 84 C120 84 156 96 156 160 Z" fill="%23047857"/><path d="M22 160 L86 84 L112 84 L48 160 Z" fill="%23059669"/><path d="M32 160 L92 86 L98 86 L40 160 Z" fill="%23fde047"/><circle cx="43" cy="50" r="9" fill="%23f5b88c"/><circle cx="117" cy="50" r="9" fill="%23f5b88c"/><circle cx="80" cy="48" r="38" fill="url(%23skinF)"/><path d="M38 50 C38 8 122 8 122 50 C122 16 108 4 80 4 C52 4 38 16 38 50 Z" fill="%23171717"/><path d="M38 50 C34 72 36 88 44 96 C46 80 42 64 40 50 Z" fill="%23171717"/><path d="M122 50 C126 72 124 88 116 96 C114 80 118 64 120 50 Z" fill="%23171717"/><circle cx="80" cy="36" r="4" fill="%23be123c"/><path d="M56 40 Q66 36 74 40" stroke="%23171717" stroke-width="2.5" fill="none" stroke-linecap="round"/><path d="M86 40 Q94 36 104 40" stroke="%23171717" stroke-width="2.5" fill="none" stroke-linecap="round"/><ellipse cx="68" cy="46" rx="4" ry="2.6" fill="%23171717"/><ellipse cx="92" cy="46" rx="4" ry="2.6" fill="%23171717"/><path d="M77 54 Q80 58 83 54" stroke="%23c2410c" stroke-width="1.8" fill="none"/><path d="M71 66 Q80 75 89 66" stroke="%23be123c" stroke-width="2.5" fill="none" stroke-linecap="round"/></svg>`;

export function getTeacherPhoto(teacher) {
  if (!teacher) return PHOTO_MALE_TEACHER;

  // 1. Direct valid raster photo_url from teacher object
  if (teacher.photo_url && typeof teacher.photo_url === 'string' && teacher.photo_url.length > 50 && !teacher.photo_url.includes('data:image/svg')) {
    return teacher.photo_url;
  }

  // 2. High-capacity IndexedDB / PHOTO_CACHE custom photo
  const customVaultPhoto = getTeacherCustomPhoto(teacher);
  if (customVaultPhoto && customVaultPhoto.length > 50) {
    return customVaultPhoto;
  }

  // 3. Fallback to teacher.photo_url if present
  if (teacher.photo_url && typeof teacher.photo_url === 'string' && teacher.photo_url.length > 20) {
    return teacher.photo_url;
  }

  const desig = (teacher.designation || '').toLowerCase();
  const name = (teacher.name_bn || teacher.name_en || '').toLowerCase();
  const role = (teacher.public_contact_role || teacher.role || '').toLowerCase();
  const empId = (teacher.employee_id || teacher.id || '').toLowerCase();
  
  if (role === 'head_teacher' || (desig.includes('প্রধান শিক্ষক') && !desig.includes('সহকারী')) || name.includes('শফিকুল')) {
    return PHOTO_HEAD_TEACHER;
  }
  if (role === 'assistant_head_teacher' || desig.includes('সহকারী প্রধান শিক্ষক') || name.includes('তাপসী')) {
    return PHOTO_ASST_HEAD_TEACHER;
  }
  if (role === 'ict_teacher' || desig.includes('আইসিটি') || (teacher.subject && teacher.subject.includes('আইসিটি')) || name.includes('আবুবকর')) {
    return PHOTO_ICT_TEACHER;
  }
  if (role === 'office_assistant' || desig.includes('অফিস') || desig.includes('হিসাব') || name.includes('আলমগীর') || empId.startsWith('stf')) {
    return PHOTO_OFFICE_ASSISTANT;
  }
  if (name.includes('আশরাফুল') || name.includes('ashraful')) {
    return PHOTO_TEACHER_ASHRAFUL;
  }
  if (name.includes('কান্তা') || name.includes('kanta')) {
    return PHOTO_TEACHER_KANTA_MONI;
  }
  if (name.includes('রফিকুল') || name.includes('rafiqul')) {
    return PHOTO_TEACHER_RAFIQUL;
  }
  if (teacher.gender === 'female' || teacher.gender === 'নারী' || name.includes('খাতুন') || name.includes('বেগম') || name.includes('সুলতানা') || name.includes('আক্তার') || name.includes('রোকসানা') || name.includes('ফরিদা') || name.includes('সরকার')) {
    return PHOTO_FEMALE_TEACHER;
  }
  return PHOTO_MALE_TEACHER;
}

